from dataclasses import dataclass, field
from typing import Any, List, Optional


class Expr:
    """Base class for all expression nodes."""

    text = ""


@dataclass
class Literal(Expr):
    value: Any


@dataclass
class Column(Expr):
    name: str


@dataclass
class UnaryOp(Expr):
    op: str  # "-" or "NOT" (canonical uppercase)
    operand: Expr


@dataclass
class BinaryOp(Expr):
    op: str  # OR, AND, =, !=, <>, <, <=, >, >=, +, -, *, /, ||
    left: Expr
    right: Expr


@dataclass
class IsNull(Expr):
    operand: Expr
    negated: bool = False


@dataclass
