"""Query execution: turn parsed SELECT statements into result rows."""

from functools import cmp_to_key
from typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple

from .errors import QueryError
from .expr import (
    AGGREGATES,
    compare_values,
    contains_aggregate,
    evaluate,
    validate,
)
from .nodes import (
    Between,
    BinaryOp,
    Column,
    Expr,
    FuncCall,
    InList,
    IsNull,
    Like,
    Literal,
    OrderItem,
    Select,
    SelectItem,
    UnaryOp,
)
from .parser import parse
from .result import Result
from .table import load_table


def execute(sql: str, directory: str = ".") -> Result:
    """Parse and run ``sql``, reading table files from ``directory``."""
    select = parse(sql)
    table = load_table(directory, select.table)
    columns = table.columns

    items, output_names = _projection(select, columns)
    order_refs = [_order_ref(item.expr, output_names) for item in select.order_by]

    # Validate every expression up front so that unknown columns/functions are
    # reported even when no rows survive filtering.
    if select.where is not None:
        validate(select.where, columns, allow_aggregates=False)
    for expr in select.group_by:
        validate(expr, columns, allow_aggregates=False)
    for item in items:
        validate(item.expr, columns, allow_aggregates=True)
    if select.having is not None:
        validate(select.having, columns, allow_aggregates=True)
    for ref, item in zip(order_refs, select.order_by):
        if ref is None:
            validate(item.expr, columns, allow_aggregates=True)

    grouped = bool(select.group_by)
    if any(contains_aggregate(item.expr) for item in items):
        grouped = True
    if select.having is not None and contains_aggregate(select.having):
        grouped = True
    if any(contains_aggregate(item.expr) for item in select.order_by):
        grouped = True

    if grouped:
        group_keys = {_expr_key(expr) for expr in select.group_by}
        for item in items:
            _validate_grouped(item.expr, group_keys)
        if select.having is not None:
            _validate_grouped(select.having, group_keys)
        for ref, item in zip(order_refs, select.order_by):
            if ref is None:
                _validate_grouped(item.expr, group_keys)

    # WHERE always works on plain input rows.
    filtered = table.rows
    if select.where is not None:
        filtered = [
            row
            for row in filtered
            if _is_true(evaluate(select.where, columns, row))
        ]

    records = _build_records(
        select, items, order_refs, columns, filtered, grouped
    )

    if select.distinct:
        records = _distinct(records)

    if select.order_by:
        records.sort(key=cmp_to_key(lambda a, b: _compare_records(a, b, select.order_by)))

    offset = select.offset or 0
    if offset < 0:
        raise QueryError("OFFSET must not be negative")
    if select.limit is not None:
        if select.limit < 0:
            raise QueryError("LIMIT must not be negative")
        records = records[offset : offset + select.limit]
    elif offset:
        records = records[offset:]

    return Result(output_names, [tuple(values) for values, _ in records])


# ---------------------------------------------------------------------------
# Projection


def _projection(select: Select, columns: Sequence[str]):
    if select.star:
        items = [SelectItem(Column(name)) for name in columns]
        return items, list(columns)

    items = select.items
    names: List[str] = []
    for item in items:
        if item.alias is not None:
            names.append(item.alias)
        elif isinstance(item.expr, Column):
            index = _column_index(columns, item.expr.name)
            names.append(columns[index])
        else:
            text = item.expr.text
            names.append(text if text else repr(item.expr))
    return items, names


def _column_index(columns: Sequence[str], name: str) -> int:
    lowered = name.lower()
    for index, column in enumerate(columns):
        if column.lower() == lowered:
            return index
    raise QueryError("unknown column: %s" % name)


# ---------------------------------------------------------------------------
# Grouping validation


def _children(expr: Expr) -> List[Expr]:
    if isinstance(expr, UnaryOp):
        return [expr.operand]
    if isinstance(expr, BinaryOp):
        return [expr.left, expr.right]
    if isinstance(expr, IsNull):
        return [expr.operand]
    if isinstance(expr, InList):
        return [expr.operand] + list(expr.items)
    if isinstance(expr, Between):
        return [expr.operand, expr.low, expr.high]
    if isinstance(expr, Like):
        return [expr.operand, expr.pattern]
    if isinstance(expr, FuncCall):
        return list(expr.args)
    return []


def _normal_op(op: str) -> str:
    op = op.upper() if op.isalpha() else op
    if op == "<>":
        return "!="
    return op


def _expr_key(expr: Expr):
    """Return a structural key used to compare with GROUP BY expressions."""
    if isinstance(expr, Literal):
        return ("literal", type(expr.value).__name__, expr.value)
    if isinstance(expr, Column):
        return ("column", expr.name.lower())
    if isinstance(expr, UnaryOp):
        return ("unary", _normal_op(expr.op), _expr_key(expr.operand))
    if isinstance(expr, BinaryOp):
        return (
            "binary",
            _normal_op(expr.op),
            _expr_key(expr.left),
            _expr_key(expr.right),
        )
    if isinstance(expr, IsNull):
        return ("isnull", expr.negated, _expr_key(expr.operand))
    if isinstance(expr, InList):
        return (
            "in",
            expr.negated,
            _expr_key(expr.operand),
            tuple(_expr_key(item) for item in expr.items),
        )
    if isinstance(expr, Between):
        return (
            "between",
            expr.negated,
            _expr_key(expr.operand),
            _expr_key(expr.low),
            _expr_key(expr.high),
        )
    if isinstance(expr, Like):
        return (
            "like",
            expr.negated,
            _expr_key(expr.operand),
            _expr_key(expr.pattern),
        )
    if isinstance(expr, FuncCall):
        return (
            "call",
            expr.name.upper(),
            expr.star,
            tuple(_expr_key(arg) for arg in expr.args),
        )
    return ("other", repr(expr))


def _validate_grouped(expr: Expr, group_keys) -> None:
    """Reject columns that are neither grouped nor inside an aggregate."""
    if isinstance(expr, FuncCall) and expr.name.upper() in AGGREGATES:
        return
    if _expr_key(expr) in group_keys:
        return
    children = _children(expr)
    if not children:
        if isinstance(expr, Column):
            raise QueryError(
                "column %s must appear in GROUP BY" % expr.name
            )
        return
    for child in children:
        _validate_grouped(child, group_keys)


# ---------------------------------------------------------------------------
# Rows, grouping, and ordering


def _build_records(
    select: Select,
    items: Sequence[SelectItem],
    order_refs: Sequence[Optional[int]],
    columns: Sequence[str],
    filtered: Sequence[Sequence[Any]],
    grouped: bool,
):
    """Build (output_values, order_key_values) pairs."""
    records = []

    if grouped:
        if select.group_by:
            groups: List[List[Sequence[Any]]] = []
            lookup: Dict[Tuple[Any, ...], int] = {}
            for row in filtered:
                key = tuple(
                    evaluate(expr, columns, row) for expr in select.group_by
                )
                try:
                    index = lookup[key]
                except KeyError:
                    index = len(groups)
                    lookup[key] = index
                    groups.append([])
                groups[index].append(row)
        else:
            # Without GROUP BY, every row (even none) is one group.
            groups = [list(filtered)]

        for group in groups:
            row = group[0] if group else [None] * len(columns)
            if select.having is not None:
                if not _is_true(evaluate(select.having, columns, row, group)):
                    continue
            values = [
                evaluate(item.expr, columns, row, group) for item in items
            ]
            keys = _order_keys(
                select, order_refs, columns, row, group, values
            )
            records.append((values, keys))
        return records

    for row in filtered:
        if select.having is not None:
            if not _is_true(evaluate(select.having, columns, row, None)):
                continue
        values = [evaluate(item.expr, columns, row, None) for item in items]
        keys = _order_keys(select, order_refs, columns, row, None, values)
        records.append((values, keys))
    return records


def _order_keys(
    select: Select,
    order_refs: Sequence[Optional[int]],
    columns: Sequence[str],
    row: Sequence[Any],
    group,
    values: Sequence[Any],
):
    keys = []
    for ref, item in zip(order_refs, select.order_by):
        if ref is not None:
            keys.append(values[ref])
        else:
            keys.append(evaluate(item.expr, columns, row, group))
    return keys


def _order_ref(expr: Expr, output_names: Sequence[str]) -> Optional[int]:
    """Return the output index for a name/position ORDER BY item, else None."""
    if isinstance(expr, Column):
        lowered = expr.name.lower()
        for index, name in enumerate(output_names):
            if name.lower() == lowered:
                return index
    if isinstance(expr, Literal) and type(expr.value) is int:
        index = expr.value - 1
        if index < 0 or index >= len(output_names):
            raise QueryError(
                "ORDER BY position %d is out of range" % expr.value
            )
        return index
    return None


def _compare_records(a, b, order_by: Sequence[OrderItem]) -> int:
    for index, item in enumerate(order_by):
        result = _compare_for_sort(a[1][index], b[1][index], item.desc)
        if result:
            return result
    return 0


def _compare_for_sort(left: Any, right: Any, desc: bool) -> int:
    if left is None and right is None:
        return 0
    if left is None:
        # NULLs first ascending, last descending.
        return 1 if desc else -1
    if right is None:
        return -1 if desc else 1
    result = compare_values(left, right)
    return -result if desc else result


def _distinct(records):
    seen = set()
    unique = []
    for values, keys in records:
        marker = tuple(values)
        if marker not in seen:
            seen.add(marker)
            unique.append((values, keys))
    return unique


def _is_true(value: Any) -> bool:
    if value is None:
        return False
    if type(value) is not bool:
        raise QueryError("condition must be true or false")
    return value

